corrected_code:
const express = require('express');
const { Appointment } = require('../models/appointment');

const app = express();
app.use(express.json());

const clinicApp = express({ mergeParams: true });
app.use('/clinics/:clinicId/departments', clinicApp);

clinicApp.put('/:deptId/appointments/:appointmentId/reschedule', async (req, res) => {
  if (!req.session || !req.session.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { newSlotTime } = req.body;

  // Verify that the appointment matches clinicId, deptId, and user ownership
  const appointment = await Appointment.findOne({
    _id: req.params.appointmentId,
    clinicId: req.params.clinicId,
    departmentId: req.params.deptId
  });

  if (!appointment) {
    return res.status(404).json({ error: 'Appointment not found in this department' });
  }

  // Ensure only the patient or clinical staff can reschedule
  const isOwner = appointment.patientId.toString() === req.session.userId;
  const isStaff = req.session.role === 'CLINIC_STAFF';

  if (!isOwner && !isStaff) {
    return res.status(403).json({ error: 'Access denied: cannot reschedule another patient\'s appointment' });
  }

  appointment.scheduledTime = newSlotTime;
  await appointment.save();

  res.json({ success: true, appointment });
});

app.listen(6000);
